import json
N=28
out=[[0]*N for _ in range(N)]
seps={4,9,14,19,24}
for i in seps:
 out[i]=[8]*N
 for r in range(N): out[r][i]=8
bounds=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
# Draw line segments on the 6x6 panel lattice implied by same-color marker pairs.
lines={2:{(1,c) for c in range(5)}|{(r,0) for r in range(1,4)}, 3:{(r,2) for r in range(5)}}
# Overlaps of different colored lines become 6, as in the demo.
for (pr,pc),color in lines[2].items():
 r0,r1=bounds[pr]; c0,c1=bounds[pc]
 for r in range(r0,r1):
  for c in range(c0,c1): out[r][c]=color
for (pr,pc),color in lines[3].items():
 r0,r1=bounds[pr]; c0,c1=bounds[pc]
 for r in range(r0,r1):
  for c in range(c0,c1): out[r][c]=6 if out[r][c]==2 else color
assert len(out)==28 and all(len(x)==28 for x in out)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

